<?php
declare(strict_types=1);
require_once __DIR__.'/db.php';
$recipes=$pdo->query("SELECT id,recipe_name,recipe_name_ta,recipe_name_th,base_yield,base_unit FROM recipes ORDER BY recipe_name")->fetchAll();
$error='';$result=null;$lang=(string)($_POST['lang']??'en');if(!in_array($lang,['en','ta','th'],true))$lang='en';
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$id=filter_var($_POST['recipe_id']??null,FILTER_VALIDATE_INT);$qty=trim((string)($_POST['quantity']??''));$unit=strtolower(trim((string)($_POST['unit']??'g')));
 if(!$id)$error='Please select a recipe from the dropdown.';
 elseif(!is_numeric($qty)||(float)$qty<=0||(float)$qty>100000)$error='Enter a valid positive quantity (maximum 100000).';
 else{
  try{
   $st=$pdo->prepare('SELECT * FROM recipes WHERE id=?');$st->execute([$id]);$r=$st->fetch();
   if(!$r)$error='Recipe not found in the database.';
   else{
    $base=(float)($r['base_yield']??1);$baseUnit=strtolower(trim((string)($r['base_unit']??'g')));
    $norm=static function(string $u):string{$u=strtolower(trim($u));return ['gram'=>'g','grams'=>'g','kilogram'=>'kg','kilograms'=>'kg','l'=>'litre','liter'=>'litre','liters'=>'litre','litres'=>'litre','millilitre'=>'ml','millilitres'=>'ml','milliliter'=>'ml','milliliters'=>'ml'][$u]??$u;};
    $type=static function(string $u)use($norm):string{$u=$norm($u);return in_array($u,['g','kg'],true)?'weight':(in_array($u,['ml','litre'],true)?'volume':(in_array($u,['piece','pieces','count'],true)?'count':'other'));};
    $toBase=static function(float $q,string $u)use($norm):float{return in_array($norm($u),['kg','litre'],true)?$q*1000:$q;};
    $unit=$norm($unit);$baseUnit=$norm($baseUnit);
    if($base<=0)$error='This recipe has an invalid base yield. Please correct it in Admin.';
    elseif($type($unit)!==$type($baseUnit)||$type($unit)==='other')$error='Choose a compatible unit: g/kg for weight or ml/litre for volume.';
    else{
     $factor=$toBase((float)$qty,$unit)/$toBase($base,$baseUnit);$raw=(string)$r['ingredients'];$items=json_decode($raw,true);$ings=[];
     if(is_array($items)){
      foreach($items as $it){if(!is_array($it))continue;$iq=isset($it['quantity'])&&is_numeric($it['quantity'])?(float)$it['quantity']:null;$iu=$norm((string)($it['unit']??''));$name=(string)($it['name']??$it['name_en']??'Ingredient');$display='';if($iq!==null){$scaled=$iq*$factor;$display=(abs($scaled-round($scaled))<0.000001?(string)(int)round($scaled):rtrim(rtrim(number_format($scaled,3,'.',''),'0'),'.')).($iu!==''?' '.$iu:'');}$ings[]=['name_en'=>$name,'name_ta'=>(string)($it['name_ta']??''),'name_th'=>(string)($it['name_th']??''),'display_quantity'=>$display];}
     } else {
      foreach(preg_split('/\r\n|\r|\n/',$raw)?:[] as $line){$line=trim(preg_replace('/^[\s\-•*]+/u','',$line)??$line);if($line==='')continue;
       if(preg_match('~^(.*?)\s*(?:–|—|-|:)?\s*(\d+(?:\.\d+)?|\d+\s*/\s*\d+|½|¼|¾|⅓|⅔)\s*(kg|kilograms?|g|grams?|ml|millilitres?|milliliters?|litres?|liters?|l|tsp|teaspoons?|tbsp|tablespoons?|cups?)\b~iu',$line,$m)){
        $n=trim($m[2]);$map=['½'=>.5,'¼'=>.25,'¾'=>.75,'⅓'=>1/3,'⅔'=>2/3];if(isset($map[$n]))$iq=$map[$n];elseif(str_contains($n,'/')){[$a,$b]=array_map('floatval',preg_split('~/~',$n));$iq=$b==0?0:$a/$b;}else $iq=(float)$n;
        $scaled=$iq*$factor;$display=(abs($scaled-round($scaled))<0.000001?(string)(int)round($scaled):rtrim(rtrim(number_format($scaled,3,'.',''),'0'),'.')).' '.$norm($m[3]);$ings[]=['name_en'=>trim($m[1]),'name_ta'=>'','name_th'=>'','display_quantity'=>$display];
       }else $ings[]=['name_en'=>$line,'name_ta'=>'','name_th'=>'','display_quantity'=>''];
      }
     }
     $name=(string)($r['recipe_name']??'Recipe');$method=(string)($r['preparation_method']??'');if($lang==='ta'&&trim((string)($r['recipe_name_ta']??''))!=='')$name=(string)$r['recipe_name_ta'];elseif($lang==='th'&&trim((string)($r['recipe_name_th']??''))!=='')$name=(string)$r['recipe_name_th'];$methodCol='method_'.$lang;if(trim((string)($r[$methodCol]??''))!=='')$method=(string)$r[$methodCol];
     $result=['recipe_name'=>$name,'description'=>(string)($r['description_'.$lang]??''),'requested_quantity'=>(float)$qty,'requested_unit'=>$unit,'ingredients'=>$ings,'preparation_method'=>$method,'base_yield'=>$base,'base_unit'=>$baseUnit];
    }
   }
  }catch(PDOException $e){error_log('Calculator query: '.$e->getMessage());$error='Unable to read recipe from PostgreSQL. Check the database connection and recipe columns.';}
 }
}
function unitList():array{return [['Gram','g'],['Kilogram','kg'],['Millilitre','ml'],['Litre','litre']];}
?>
