s{display:flex;gap:10px;flex-wrap:wrap;margin-top:20px}footer{text-align:center;padding:22px;color:var(--muted);font-size:13px}@media(max-width:600px){.grid{grid-template-columns:1fr}.wide{grid-column:auto}.actions .btn{width:100%}.ingredient{align-items:flex-start}}@media print{.hero,.nav,form,.actions,footer{display:none}.card{box-shadow:none;border:0}}
</style></head><body><header class="hero"><h1>🥭 Smart Recipe Hub</h1><p></p></header><nav class="nav"><a href="index.php">Home</a><a href="calculator.php">Calculator</a><a href="recipes.php"></a><a href="profile.php">Profile</a><a href="logout.php">Logout</a></nav><main class="wrap">
<section class="card"><h2>Calculate ingredients</h2><p class="muted"></p><?php if($error!==''):?><div class="alert" role="alert"><?=h($error)?></div><?php endif;?>
<form method="post"><?=csrf_field()?><div class="grid"><div class="field wide"><label for="recipe_id">Recipe</label><select id="recipe_id" name="recipe_id" required><option value="">Choose saved recipe</option><?php foreach($recipes as $r):$display=match($lang){'ta'=>($r['recipe_name_ta']?:$r['recipe_name']),'th'=>($r['recipe_name_th']?:$r['recipe_name']),default=>$r['recipe_name']};?><option value="<?=(int)$r['id']?>" <?=((string)($_POST['recipe_id']??'')===(string)$r['id'])?'selected':''?>><?=h($display)?></option><?php endforeach;?></select></div><div class="field"><label for="quantity">Required quantity</label><input type="number" id="quantity" name="quantity" min=".01" max="100000" step="any" value="<?=h($_POST['quantity']??'500')?>" required></div><div class="field"><label for="unit">Unit</label><select id="unit" name="unit"><?php foreach(unitList() as [$n,$u]):?><option value="<?=h($u)?>" <?=((string)($_POST['unit']??'g')===$u)?'selected':''?>><?=h("$n ($u)")?></option><?php endforeach;?></select></div><div class="field wide"><label for="lang">Language / மொழி</label><select id="lang" name="lang"><option value="en" <?=$lang==='en'?'selected':''?>>English</option><option value="ta" <?=$lang==='ta'?'selected':''?>>தமிழ்</option><option value="th" <?=$lang==='th'?'selected':''?>>Thanglish</option></select></div></div><button class="btn" type="submit">✨ Calculate recipe</button></form></section>
<?php if(is_array($result)):?><section class="card" id="result"><div style="display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;align-items:start"><div><h2 id="recipeTitle"><?=h($result['recipe_name'])?></h2><?php if(trim((string)$result['description'])!==''):?><p><?=nl2br(h($result['description']))?></p><?php endif;?></div><div class="yield"><?=h($result['requested_quantity'].' '.$result['requested_unit'])?></div></div><h3>🥣 Ingredients</h3><?php foreach($result['ingredients'] as $ing):?><div class="ingredient"><span><?=h($lang==='ta'&&$ing['name_ta']!==''?$ing['name_ta']:($lang==='th'&&$ing['name_th']!==''?$ing['name_th']:$ing['name_en']))?></span><strong class="amount"><?=h($ing['display_quantity'])?></strong></div><?php endforeach;?><h3 style="margin-top:25px">👩‍🍳 Preparation method</h3><?php if(trim((string)$result['preparation_method'])!==''):?><div><?=nl2br(h($result['preparation_method']))?></div><?php else:?><p class="muted">Method is not available in this language yet.</p><?php endif;?><p class="muted">Base yield: <?=h($result['base_yield'].' '.$result['base_unit'])?>. Cooking and drying can change the actual final yield.</p><div class="actions"><button class="btn" onclick="window.print()">🖨️ Print</button><button class="btn btn-light" onclick="downloadResult()">⬇️ Download TXT</button></div></section><?php endif;?></main><footer>Smart Recipe Hub · Cook smart, measure better 🌿</footer><script>function downloadResult(){const el=document.getElementById('result');if(!el)return;const name=(document.getElementById('recipeTitle')?.innerText||'recipe').replace(/[^a-z0-9_-]/gi,'_');const blob=new Blob([el.innerText],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name+'_recipe.txt';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}</script></body></html>
